// Crossref describes each new article: title, DOI link, publication date and,
// when the publisher sent one, the abstract. That is all we use. The article
// itself is never fetched.
const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const works = (($input.first().json.message || {}).items) || [];
return works.map(w => {
  const p = ((w.published || {})['date-parts'] || [[]])[0];
  const date = p[0] ? new Date(Date.UTC(p[0], (p[1] || 1) - 1, p[2] || 1)).toISOString() : null;
  const abstract = strip(w.abstract).replace(/^Abstract\s*/i, '');
  return { json: {
    url: w.URL || null,
    title: strip((w.title || [])[0]) || null,
    published_at: date,
    excerpt: abstract.slice(0, 300),
    text: abstract,
    publisher: (w['container-title'] || [])[0] || null,
  } };
});

// The same shape as the Crossref branch, so everything after this point does
// not care where an article came from. A date we cannot read is left empty.
const strip = s => String(s || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const iso = d => { const t = d ? new Date(d) : null; return t && !isNaN(t) ? t.toISOString() : null; };
return $input.all().map(i => {
  const e = i.json;
  const text = strip(e.content || e['content:encoded'] || e.summary || e.contentSnippet);
  return { json: {
    url: e.link || null,
    title: strip(e.title) || null,
    published_at: iso(e.isoDate || e.pubDate || e.pubdate),
    excerpt: text.slice(0, 300),
    text,
    publisher: null,
  } };
});

// Most feeds carry only a teaser. For public news pages whose robots.txt
// allows it (fetch_full_text on the source), read the article itself. Journals
// never come here: their text is the abstract and nothing more.
const src = $('Start').first().json;
const a = $json;
if (!a.url || !src.fetch_full_text) return { json: a };

const unescape = s => String(s)
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&#0?39;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

try {
  const html = String(await this.helpers.httpRequest({
    url: a.url, timeout: 15000, json: false,
    headers: { 'User-Agent': 'DFP newsletter bot (HAMK student project)' },
  }));
  // Pages differ, so every likely article container is tried and the one
  // holding the most paragraph text wins. Government sites, for example, put
  // the language picker in the same kind of block as the article, and taking
  // the first block gave the picker. Menus, headers and footers are dropped
  // before paragraphs are read.
  const paragraphs = region => [...region
      .replace(/<(script|style|noscript|nav|header|footer|aside|form|figure|svg)\b[\s\S]*?<\/\1>/gi, ' ')
      .matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)]
    .map(x => unescape(x[1].replace(/<[^>]+>/g, ' ')))
    .filter(t => t.length > 40);
  const marks = /<(?:article|main)\b|class="[^"]*\b(?:journal-content-article|entry-content|article-body|post-content|single-content)\b/gi;
  const starts = [...html.matchAll(marks)].map(m => m.index);
  const regions = starts.length ? starts.map((st, i) => html.slice(st, starts[i + 1] ?? html.length)) : [html];
  let best = [];
  for (const r of regions) {
    const p = paragraphs(r);
    if (p.join('').length > best.join('').length) best = p;
  }
  const text = best.join('\n').slice(0, 6000);
  // Keep the feed's own text if the page gave us less.
  if (text.length > (a.text || '').length) return { json: { ...a, text } };
} catch (e) {
  // A page that will not load still leaves the feed's text, and the item is stored.
}
return { json: a };

// One call to the ingest API per source. The API checks every article and
// stores the good ones, so this workflow never writes to Postgres itself.
const src = $('Start').first().json;
let listed = 0;
for (const reader of ['Feed items', 'Crossref items']) {
  try { listed = $(reader).all().length; break; } catch (e) { /* the other branch ran */ }
}
const read = $input.all().map(i => i.json).filter(a => a.url && a.title);
return [{ json: {
  found: listed,
  unreadable: 0,
  body: { items: read.map(a => ({
    source_id: Number(src.source_id),
    url: a.url,
    title: a.title,
    publisher: a.publisher || src.publisher || null,
    published_at: a.published_at,
    excerpt: a.excerpt || null,
    raw_text: a.text || null,
  })) },
} }];

// What the schedule writes to collection_runs for this source.
const batch = $('Build batch').first().json;
const results = $json.results || [];
const rejected = results.filter(r => !r.accepted);

const problems = [];
if (batch.unreadable) problems.push(`${batch.unreadable} article(s) could not be read`);
if (rejected.length) problems.push(`${rejected.length} rejected: ` +
  [...new Set(rejected.map(r => r.reason))].join(', '));

return [{ json: {
  items_found: batch.found,
  items_new: results.filter(r => r.accepted && r.new).length,
  error: problems.length ? problems.join('; ') : null,
} }];
